#include "tests/contract/authorization/send_cases.hpp"
int main(int argc,char** argv){try {using namespace policy_test;CHECK(argc==2);Env env;auto sink=std::make_shared<Sink>();auto send=send_cases::sender(env.session,sink);CHECK(send->enqueue_response(send_cases::response(env)));CHECK(send->enqueue_response(send_cases::response(env)));CHECK(sink->pending==4);if(std::string(argv[1])=="close_control"){CHECK(env.session->close());}else{sink->result=StartResult::Unknown;CHECK(send->start_next()==StartResult::Unknown);CHECK(!env.caller->view().revalidate());}std::cout<<"pending="<<sink->pending<<" size="<<sink->size<<"\n";CHECK(sink->pending==0);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
